const film=$('#filmTrack');film.replaceChildren();
countries.forEach((country,i)=>{const cities=destinations.filter(d=>d.country===country),count=cities.reduce((s,d)=>s+d.photos.length,0),cover=cities.flatMap(d=>d.photos).find(Boolean);const b=document.createElement('button');b.className='atlas-card country-card';b.dataset.region=region(country);b.dataset.country=country;b.innerHTML=`${cover?`<img class="country-cover" src="${assetSrc(cover.src)}" alt="" loading="lazy">`:''}<div class="country-shade" aria-hidden="true"></div><div class="country-orbit" aria-hidden="true"><i></i><i></i><b>${String(i+1).padStart(2,'0')}</b></div><span>PERSONAL ATLAS / ${cities.length} ${cities.length===1?'CITY':'CITIES'}</span><h3>${country}</h3><p>${count} photographs · Open country ↗</p>`;b.onclick=()=>openCountry(country);grid.append(b);const chip=document.createElement('button');chip.className='country-film';chip.innerHTML=`${cover?`<img class="country-film-cover" src="${assetSrc(cover.src)}" alt="" loading="lazy">`:''}<span>${String(i+1).padStart(2,'0')}</span><strong>${country}</strong><small>${cities.map(d=>d.city).join(' · ')} ↗</small>`;chip.onclick=()=>openCountry(country);film.append(chip);});
const dialog=document.createElement('dialog');dialog.className='flight-gallery';dialog.setAttribute('aria-labelledby','flightTitle');
dialog.innerHTML=`<header><div><p id="flightCountry"></p><h2 id="flightTitle"></h2></div><button id="flightClose" aria-label="Close gallery">Close ×</button></header><nav class="city-tabs" aria-label="Cities in this country"></nav><div class="city-story"></div><div class="flight-stage"><img id="flightImage" alt=""><button class="flight-prev" aria-label="Previous photo">←</button><button class="flight-next" aria-label="Next photo">→</button></div><div class="flight-copy" aria-live="polite"><span id="flightKind"></span><p id="flightCaption"></p></div><div class="flight-tools"><button id="flightAuto" aria-pressed="false">Play journey</button><button id="flightZoom" aria-pressed="false">Zoom in</button><span id="flightNumber"></span></div><div class="flight-thumbs" aria-label="Choose a photograph"></div><section class="city-evidence"></section>`;
document.body.append(dialog);
const img=$('#flightImage'),stage=dialog.querySelector('.flight-stage');
let frames=[],index=0,auto=null,zoom=false,drag=null,pan={x:0,y:0},returnFocus=null,currentCity=null,closing=false;
function stop(){clearInterval(auto);auto=null;$('#flightAuto').textContent='Play journey';$('#flightAuto').setAttribute('aria-pressed','false');}
function roll(el,close=false){if(!motion()||currentCity?.sacred)return Promise.resolve();return el.animate(close?[{opacity:1,transform:'perspective(1000px) rotateX(0)'},{opacity:0,transform:'perspective(1000px) rotateX(-12deg) translateY(32px) scaleY(.8)'}]:[{opacity:0,transform:'perspective(1000px) rotateX(14deg) translateY(24px) scaleY(.82)'},{opacity:1,transform:'perspective(1000px) rotateX(0) translateY(0) scaleY(1)'}],{duration:close?180:400,easing:'cubic-bezier(.2,.8,.2,1)'}).finished.catch(()=>{});}
function setZoom(value){zoom=value;pan={x:0,y:0};img.style.transform=value?'scale(2)':'none';stage.classList.toggle('is-zoomed',value);$('#flightZoom').textContent=value?'Zoom out':'Zoom in';$('#flightZoom').setAttribute('aria-pressed',String(value));}
function show(i){if(!frames.length)return;index=(i+frames.length)%frames.length;setZoom(false);const f=frames[index];img.onerror=()=>{img.removeAttribute('src');img.alt='Photograph unavailable';$('#flightCaption').textContent='This photograph is temporarily unavailable. The destination story remains available.';};img.src=f.src;img.alt=f.caption;$('#flightCaption').textContent=f.caption;$('#flightKind').textContent=f.kind;$('#flightNumber').textContent=`${index+1} / ${frames.length}`;dialog.querySelectorAll('.flight-thumbs button').forEach((b,j)=>b.setAttribute('aria-current',String(j===index)));roll(img);if(!currentCity?.sacred)journeyAudio.play('photo-discover',.22);}
function populate(items){stop();frames=[...new Map(items.map(p=>[p.src,p])).values()];const thumbs=dialog.querySelector('.flight-thumbs');thumbs.replaceChildren();stage.hidden=!frames.length;$('.flight-tools').hidden=!frames.length;$('.flight-copy').hidden=!frames.length;frames.forEach((f,i)=>{const b=document.createElement('button');b.setAttribute('aria-label','View photograph '+(i+1));const im=new Image();im.src=f.src;im.alt='';im.loading='lazy';im.onerror=()=>{b.hidden=true;};b.append(im);b.onclick=()=>{stop();show(i);};thumbs.append(b);});$('#flightAuto').disabled=frames.length<2;dialog.querySelectorAll('.flight-prev,.flight-next').forEach(b=>b.disabled=frames.length<2);if(frames.length)show(0);}
function open(){closing=false;if(!dialog.open){returnFocus=document.activeElement;dialog.showModal();document.body.classList.add('gallery-open');roll(dialog);$('#flightClose').focus();}dialog.scrollTop=0;journeyAudio.mix();}
function evidence(d){const el=dialog.querySelector('.city-evidence');el.replaceChildren();const facts=[];if(d.city==='London')facts.push(['Education','MSc Computer Science · University of East London · Distinction.'],['Professional chapter','Cybersecurity Engineer at NCC Group.'],['Seasonal umpiring','Last Man Stands, England · recorded as ZR Saimon (LS).']);if(d.city==='Portsmouth')facts.push(['Education','MSc Cybersecurity & Forensic IT · University of Portsmouth.']);if(d.city==='Dhaka')facts.push(['Education','BSc Computer Science & Engineering · AIUB.']);if(d.sacred)facts.push(['Spiritual journey',d.story]);for(const [title,copy] of facts){const a=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=title;p.textContent=copy;a.append(h,p);el.append(a);}document.querySelectorAll('.conference-card').forEach(card=>{const location=card.querySelector('.conference-card__top p')?.textContent||'';if(!location.toLowerCase().includes(d.city.toLowerCase()))return;const a=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p'),b=document.createElement('button');h.textContent=card.querySelector('h3').textContent;p.textContent=location+' · Supplied event-ticket archive';b.textContent='View event evidence ↗';b.onclick=()=>card.querySelector('.ticket-open').click();a.append(h,p,b);el.append(a);});if(d.city==='London'){const a=document.createElement('a');a.href='https://www.lastmanstands.com/lms-cricket/match-centre/info/459959';a.target='_blank';a.rel='noopener';a.textContent='Official LMS umpiring match record ↗';el.append(a);}}
function tabs(country,selected){const nav=dialog.querySelector('.city-tabs');nav.replaceChildren();destinations.filter(d=>d.country===country).forEach(d=>{const b=document.createElement('button'),cover=d.photos[0];b.className='city-tab';if(cover){const image=new Image();image.src=assetSrc(cover.src);image.alt='';image.loading='lazy';image.onerror=()=>image.remove();b.append(image);}const label=document.createElement('span');label.textContent=d.city;b.append(label);b.setAttribute('aria-current',String(d.city===selected));b.onclick=()=>openCity(d.city);nav.append(b);});}
function openCity(name){const d=getDestination(name);if(!d)return;currentCity=d;announceDestination(d.city);$('#flightTitle').textContent=d.city;$('#flightCountry').textContent=d.country;tabs(d.country,d.city);const story=dialog.querySelector('.city-story');story.textContent=d.story;const drive=document.createElement('button');drive.className='chapter-drive';drive.textContent=`Enter ${d.city} road scene ↗`;drive.onclick=()=>{dialog.close();document.body.classList.remove('gallery-open');window.zrDrive?.travelCity(d.city);window.zrDrive?.setMode('drive');};story.append(drive);populate(d.photos);if(!d.photos.length){const p=document.createElement('p');p.className='archive-note';p.textContent='No city-specific personal photograph in this collection yet.';story.append(p);if(nearby[d.city]){const b=document.createElement('button');b.textContent=`Explore ${nearby[d.city]} photographs instead ↗`;b.onclick=()=>openCity(nearby[d.city]);story.append(b);}}evidence(d);open();}
function openCountry(country){const first=destinations.find(d=>d.country===country);if(first)openCity(first.city);if(country==='Türkiye'&&extraArchive.Türkiye.length){const b=document.createElement('button');b.textContent='Türkiye · other memories';b.onclick=()=>window.zrOpenGallery('Türkiye',extraArchive.Türkiye,'Türkiye');dialog.querySelector('.city-tabs').append(b);}}
window.zrOpenCity=openCity;window.zrOpenCountry=openCountry;
window.zrOpenGallery=(title,items,country='Personal archive')=>{const d=getDestination(title);if(d){openCity(d.city);return;}currentCity=null;$('#flightTitle').textContent=title;$('#flightCountry').textContent=country;dialog.querySelector('.city-tabs').replaceChildren();dialog.querySelector('.city-story').textContent='';dialog.querySelector('.city-evidence').replaceChildren();populate(items);open();};
