$('#flightClose').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('close',()=>{stop();document.body.classList.remove('gallery-open');journeyAudio.mix();returnFocus?.focus({preventScroll:true});});
