dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();stop();show(index+(e.key==='ArrowRight'?1:-1));}});stage.addEventListener('pointerdown',e=>{if(e.target!==img)return;drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};stage.setPointerCapture(e.pointerId);});stage.addEventListener('pointermove',e=>{if(!drag||!zoom)return;pan.x=Math.max(-stage.clientWidth/2,Math.min(stage.clientWidth/2,drag.px+e.clientX-drag.x));pan.y=Math.max(-stage.clientHeight/2,Math.min(stage.clientHeight/2,drag.py+e.clientY-drag.y));img.style.transform=`translate(${pan.x}px,${pan.y}px) scale(2)`;});stage.addEventListener('pointerup',e=>{if(drag&&!zoom&&Math.abs(e.clientX-drag.x)>50){stop();show(index+(e.clientX<drag.x?1:-1));}drag=null;});stage.addEventListener('pointercancel',()=>drag=null);
