const work=document.createElement('section');work.className='professional-update section-shell';work.innerHTML=`<p class="eyebrow">LEADERSHIP / COMMUNITY</p><h2>Responsibility,<br><em>beyond the screen.</em></h2><div class="professional-grid"><article><span>BUSINESS</span><h3>Company directorships</h3><p>Director of TRIP BHAI LTD and ESON SOFT IT LIMITED.</p><a href="https://find-and-update.company-information.service.gov.uk/company/16286072/officers" target="_blank" rel="noopener">Trip Bhai · official record ↗</a><a href="https://find-and-update.company-information.service.gov.uk/company/16999188/officers" target="_blank" rel="noopener">Eson Soft IT · official record ↗</a></article><article><span>CRICKET / ENGLAND</span><h3>Seasonal LMS umpire</h3><p>Last Man Stands match records identify ZR Saimon (LS) as an umpire. No estimated match total.</p><a href="https://www.lastmanstands.com/lms-cricket/match-centre/info/459959" target="_blank" rel="noopener">28 May 2025 · match record ↗</a><a href="https://www.lastmanstands.com/lms-cricket/match-centre/info/457013?fixtureid=457013" target="_blank" rel="noopener">29 April 2025 · match record ↗</a></article><article><span>PROFESSIONAL ARCHIVE</span><h3>A short chapter at NTV</h3><p>A brief period working at NTV, documented by the supplied personal photograph.</p><button id="ntvArchive">Open NTV photograph ↗</button></article></div>`;$('#research').before(work);$('#ntvArchive').onclick=()=>window.zrOpenGallery('NTV',extraArchive.NTV,'Professional archive');
