const lmsCard=[...document.querySelectorAll('.professional-grid article')].find(a=>a.querySelector('h3')?.textContent.includes('Seasonal LMS'));if(lmsCard){const b=document.createElement('button');b.className='lms-open-archive';b.textContent='Open complete LMS match archive ↗';lmsCard.append(b);const overlay=document.createElement('dialog');overlay.className='lms-archive-dialog';overlay.innerHTML='<button class="lms-close" aria-label="Close LMS archive">×</button><p class="eyebrow">LMS / MATCH ARCHIVE</p><h2>Every match in one place.</h2><p class="lms-archive-intro">Publicly indexed Last Man Stands records where ZR Saimon (LS) is listed as umpire. Choose a match to open its official LMS page.</p><input class="lms-search" type="search" placeholder="Search teams, year or match ID" aria-label="Search LMS matches"><div class="lms-match-list"></div>';document.body.append(overlay);const list=overlay.querySelector('.lms-match-list');const render=()=>{const q=overlay.querySelector('.lms-search').value.toLowerCase();list.innerHTML='';lmsMatches.filter(x=>x.join(' ').toLowerCase().includes(q)).forEach(([date,name,id])=>{const a=document.createElement('a');a.href=`https://www.lastmanstands.com/lms-cricket/match-centre/info/${id}`;a.target='_blank';a.rel='noopener';a.innerHTML=`<span>${date}</span><strong>${name}</strong><small>Official LMS match record ↗</small>`;list.append(a);});};render();overlay.querySelector('.lms-search').oninput=render;overlay.querySelector('.lms-close').onclick=()=>overlay.close();b.onclick=()=>overlay.showModal();}
